func validID(id string) bool {
	if id == "" || strings.TrimSpace(id) != id || strings.Contains(id, "..") {
		return false
	}
	for _, r := range id {
		if r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || strings.ContainsRune("._:-/", r) {
			continue
		}
		return false
	}
	return true
}
